cd expo && node -e "
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { readFileSync } from 'fs';

const s3 = new S3Client({ region: 'us-east-1' });
const apkPath = '../android-ivx-holdings/app/build/outputs/apk/release/app-release.apk';
const fileData = readFileSync(apkPath);

const cmd = new PutObjectCommand({
  Bucket: 'ivxholding.com',
  Key: 'apk/ivx-holdings-v1.4.6.apk',
  Body: fileData,
  ContentType: 'application/vnd.android.package-archive',
  ContentDisposition: 'attachment; filename=\"ivx-holdings-v1.4.6.apk\"',
  CacheControl: 'no-cache, no-store, must-revalidate',
});

try {
  const res = await s3.send(cmd);
  console.log('UPLOAD SUCCESS');
  console.log('ETag:', res.ETag);
  console.log('URL: https://ivxholding.com/apk/ivx-holdings-v1.4.6.apk');
} catch (e) {
  console.error('UPLOAD FAILED:', e.message);
}
" 2>&1 | tail -10

